/**
 * @file build/gen-design-tokens.mjs
 * 文件职责：由 src/tokens.css 标记段生成 extension/design.js——内容脚本/Shadow DOM
 *   的 classic 设计 token 下发文件保持与唯一语义源同步。
 * 主要内容：extractTokenSections 提取 common/light/dark 声明行并按名去重；
 *   buildDesignJs 组装完整 classic IIFE（cssFor/结构角色色/页面注入逻辑）；
 *   脚本入口把生成结果写回源树（// Generated by 头豁免 R7 文件头门禁）。
 * 模块边界：构建期代码生成，写 extension/design.js；单元测试断言源树无漂移。
 *
 * This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at https://mozilla.org/MPL/2.0/.

 */
import {readFileSync, writeFileSync} from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const SECTION_PATTERN = /\/\*\s*>>>\s*design-tokens:(common|light|dark|end)\s*\*\//gu;
const DECLARATION_PATTERN = /^\s*((?:--[\w-]+|color-scheme)\s*:[^;]+;)\s*$/u;

/**
 * 提取 tokens.css 标记段内的声明文本。段内可出现任意选择器包装（:root、@media、
 * [data-theme]），只收集 `--name: value;` 与 `color-scheme` 声明行；同名声明必须
 * 取值一致，否则视为笔误立即失败。
 * @param {string} tokensCss
 * @returns {{common:string,light:string,dark:string}} 各段去重后的声明文本
 */
export function extractTokenSections(tokensCss) {
  const markers = [...tokensCss.matchAll(SECTION_PATTERN)];
  if (markers.length < 4 || markers.at(-1)[1] !== 'end') {
    throw new Error('tokens.css 缺少 design-tokens 标记段（需要 common/light/dark/end 四个标记）');
  }
  const sections = {};
  for (let i = 0; i < markers.length; i += 1) {
    const name = markers[i][1];
    if (name === 'end') continue;
    const from = markers[i].index + markers[i][0].length;
    const to = markers[i + 1].index;
    const seen = new Map();
    for (const line of tokensCss.slice(from, to).split('\n')) {
      const match = line.match(DECLARATION_PATTERN);
      if (!match) continue;
      if (match[1].includes('`') || match[1].includes('${')) {
        throw new Error(`design-tokens:${name} 含模板占位符，无法安全生成: ${match[1].trim()}`);
      }
      const [prop] = match[1].split(':');
      const key = prop.trim();
      if (seen.has(key) && seen.get(key) !== match[1].trim()) {
        throw new Error(`design-tokens:${name} 中 ${key} 出现冲突取值`);
      }
      if (!seen.has(key)) seen.set(key, match[1].trim());
    }
    if (!seen.size) throw new Error(`design-tokens:${name} 段没有可用声明`);
    sections[name] = [...seen.values()].map(line => `    ${line}`).join('\n');
  }
  return sections;
}

/**
 * 组装 design.js 完整源码。模板结构与手写版一致：common/light/dark 三个常量由
 * tokens.css 生成，cssFor/structureRoles/structureColors/页面注入逻辑为固定尾部。
 * @param {string} tokensCss
 * @returns {string}
 */
export function buildDesignJs(tokensCss) {
  const {common, light, dark} = extractTokenSections(tokensCss);
  return `// Generated by build/gen-design-tokens.mjs from src/tokens.css; do not edit by hand.
// UI changes follow docs/design-system.md; this file is the only token source.
(() => {

  const common = \`
${common}
  \`;
  const light = \`
${light}
  \`;
  const dark = \`
${dark}
  \`;

  // Explicit selectors keep website roots untouched; Shadow DOM and extension pages
  // consume the same tokens without fetching styles or exposing extension resources.
  const cssFor = (selector, theme = 'auto') => {
    const parts = String(selector).split(',').map(part => part.trim()).filter(Boolean);
    const block = (sel, tokens) => \`\${sel} { \${common} \${tokens} }\`;
    const wrap = tokens => parts.map(part => block(part, tokens)).join('\\n');
    const themed = (attr, tokens) => parts.map(part => {
      if (part === ':root' || part === ':host') return \`\${part}\${attr} { \${tokens} }\`;
      return \`:root\${attr} \${part}, body\${attr} \${part}, \${attr} \${part} { \${tokens} }\`;
    }).join('\\n');
    let css = wrap(theme === 'dark' ? dark : light);
    if (theme === 'auto') {
      css += \`\\n@media (prefers-color-scheme: dark) {\\n\${wrap(dark)}\\n}\`;
      if (parts.some(part => part === ':host' || part.includes(':host'))) {
        css += \`\\n:host([data-theme="dark"]) { \${dark} }\`;
        css += \`\\n:host([data-theme="light"]) { \${light} }\`;
      }
      css += \`\\n\${themed('[data-theme="dark"]', dark)}\`;
      css += \`\\n\${themed('[data-theme="light"]', light)}\`;
    }
    return css;
  };
  const structureRoles = Object.freeze({clause:Object.freeze(['原句','neutral']),subject:Object.freeze(['主语','subject']),predicate:Object.freeze(['谓语','predicate']),object:Object.freeze(['宾语','object']),predicative:Object.freeze(['表语','object']),complement:Object.freeze(['补语','object']),adverbial:Object.freeze(['状语','adverbial']),attributive:Object.freeze(['定语','attributive'])});
  const structureColors = Object.freeze({subject:Object.freeze(['#1d4ed8','#38bdf8']),predicate:Object.freeze(['#d97706','#fbbf24']),object:Object.freeze(['#0f766e','#2dd4bf']),attributive:Object.freeze(['#7c3aed','#a78bfa']),adverbial:Object.freeze(['#64748b','#94a3b8']),neutral:Object.freeze(['#94a3b8','#64748b'])});
  globalThis.RoamCatDesign = Object.freeze({cssFor,structureRoles,structureColors});

  // Only extension-owned HTML opts into page-root tokens. Script injection into a
  // website has no currentScript and must never apply this theme to the website.
  if (document.currentScript?.hasAttribute('data-roamcat-page')) {
    try {
      const savedTheme = localStorage.getItem('roamcat_ui_theme') || 'auto';
      if (savedTheme === 'dark' || savedTheme === 'light') {
        document.documentElement.setAttribute('data-theme', savedTheme);
      }
      if (localStorage.getItem('roamcat_sidebar_collapsed') === 'true') {
        document.documentElement.classList.add('sidebar-collapsed');
      }
    } catch {}
    const style = document.createElement('style');
    style.dataset.roamcatUi = 'design-tokens';
    style.textContent = cssFor(':root');
    document.head.append(style);
  }
})();
`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
  const tokensCss = readFileSync(path.join(repoRoot, 'src', 'styles', 'tokens.css'), 'utf8');
  const target = path.join(repoRoot, 'roamcat-0.0.1', 'extension', 'design.js');
  writeFileSync(target, buildDesignJs(tokensCss));
  console.log('已生成 roamcat-0.0.1/extension/design.js');
}
